//! Disposable fixtures only: no real library files or preferences are touched.
use musicos_init::database::{Db,Connection,MetadataUpdate};use std::{sync::{Arc,Barrier},path::PathBuf};
#[test]fn metadata_cache_artwork_and_organization_share_the_writer_without_lock_errors(){
 let tmp=tempfile::tempdir().unwrap();let path=tmp.path().join("library.db");let root=tmp.path().join("music");std::fs::create_dir(&root).unwrap();let file=root.join("loose.flac");std::fs::write(&file,b"untouched audio bytes").unwrap();let cover=tmp.path().join("cover.png");image::RgbaImage::new(100,100).save(&cover).unwrap();let db=Db::open(&path.to_string_lossy()).unwrap();let source=db.add_library_source("reference",root.to_str().unwrap(),"Fixture").unwrap();let id=db.insert_track(file.to_str().unwrap(),"Song","Artist","Album",1,100,21).unwrap();db.assign_track_source(id,source.id).unwrap();db.set_track_cover_art(id,cover.to_str(),0).unwrap();db.toggle_favorite(id).unwrap();let playlist=db.create_playlist("Keep").unwrap();db.add_tracks_to_playlist(playlist,&[id]).unwrap();
 let barrier=Arc::new(Barrier::new(4));let mut threads=Vec::new();for kind in 0..4{let path=path.clone();let root=root.clone();let barrier=barrier.clone();threads.push(std::thread::spawn(move||{barrier.wait();match kind{0=>{let db=Db::open(&path.to_string_lossy()).unwrap();for i in 0..24{db.update_track_metadata_override(&[id],&MetadataUpdate{genre:Some(format!("Genre {i}")),..Default::default()}).unwrap();}},1=>{let c=Connection::open_background(&path).unwrap();c.execute_batch("CREATE TABLE fixture_analysis(id INTEGER PRIMARY KEY,value TEXT)").unwrap();for i in 0..24{let tx=c.unchecked_transaction().unwrap();tx.execute("INSERT OR REPLACE INTO fixture_analysis VALUES(?,?)",rusqlite::params![i,"cached analysis"]).unwrap();tx.commit().unwrap();}},2=>{for _ in 0..12{let mut lib=library(&path,&root,source.id);crate::library::canonical_artwork(&path,&mut lib).unwrap();}},_=>{for _ in 0..4{let lib=library(&path,&root,source.id);let plan=crate::file_organization::preview(&path,&lib).unwrap();if plan.moves.is_empty(){break;}if let Err(error)=crate::file_organization::apply(&path,&plan.token){assert!(error.to_string().contains("changed"),"{error:#}");}}}}}));}for thread in threads{thread.join().unwrap();}
 let lib=library(&path,&root,source.id);let plan=crate::file_organization::preview(&path,&lib).unwrap();if !plan.moves.is_empty(){crate::file_organization::apply(&path,&plan.token).unwrap();}let track=db.get_track_by_id(id).unwrap().unwrap();assert_eq!(std::fs::read(&track.path).unwrap(),b"untouched audio bytes");assert!(track.favorited);assert_eq!(db.playlist_track_count(playlist).unwrap(),1);assert_eq!(track.id,id);
}
fn library(path:&std::path::Path,root:&std::path::Path,source:i64)->crate::library::Library{let db=Db::open(&path.to_string_lossy()).unwrap();crate::library::group(musicos_desktop::models::LibrarySnapshot{tracks:db.get_tracks().unwrap().into_iter().map(musicos_desktop::local::library::track_from_init).collect(),sources:vec![musicos_desktop::models::LibrarySource{id:source,path:PathBuf::from(root),display_name:"Fixture".into(),kind:"reference".into(),enabled:true,available:true,song_count:1,..Default::default()}],..Default::default()})}
